package com.wgh.rag.agent.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/** Structured DTO for the plan JSON generated by Planner LLM. */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class PlanDTO {

    private String planId;
    private String summary;
    private List<StepDTO> steps;

    @Data
    @Builder
    @NoArgsConstructor
    @AllArgsConstructor
    public static class StepDTO {
        private String stepId;
        private Integer stepIndex;
        private String title;
        private String description;
        /** JSON array of stepId dependencies. */
        private List<String> dependsOn;
        /** Tool names the step needs. */
        private List<String> requiresTools;
        /** Whether step needs RAG retrieval. */
        private Boolean requiresRAG;
        /** One of: DATA / ANALYSIS / REPORT / ACTION / FINAL_ANSWER. */
        private String outputType;
        /** Whether this step is HITL (Human-In-The-Loop). */
        private Boolean hitl;
        /** Expected input to prompt from previous step resultSummaries. */
        private String expectedInput;
    }
}
